import {Component, HostBinding, Injector, OnInit} from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../../shared';

@Component({
    selector: 'app-success',
    templateUrl: 'success.page.html',
    styleUrls: ['success.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class SuccessPage implements OnInit {
    ContentId;
    Barcode;
    message;
    title;
    btnCon;

    constructor(
        private router: Router,
        public navCtrl: NavController,
        private route: ActivatedRoute,
        private platform: Platform
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
        this.route.queryParams.subscribe(data => {
            this.ContentId = data.ContentId;
            this.Barcode = data.Barcode;
            switch (this.ContentId) {
                case '1':
                    this.message = this.Barcode + '箱已成功封箱';
                    this.title = '封箱成功';
                    this.btnCon = '继续扫描新的箱码';
                    break;
                case '2':
                    this.message = this.Barcode + '管已成功封管';
                    this.title = '封管成功';
                    this.btnCon = '继续扫描新的预置码';
                    break;
            }
        });
    }

    ionViewWillEnter() {
        switch (this.ContentId) {
            case '1':
                this.message = this.Barcode + '箱已成功封箱';
                this.title = '封箱成功';
                this.btnCon = '继续扫描新的箱码';
                break;
            case '2':
                this.message = this.Barcode + '管已成功封管';
                this.title = '封管成功';
                this.btnCon = '继续扫描新的预置码';
                break;
        }
    }

    clean() {
        this.title = '';
        this.message = '';
        this.ContentId = undefined;
        this.Barcode = undefined;
    }

    // 路由返回
    routeBack() {
        // this.navCtrl.back();
        this.click();
    }
    click(){
        switch (this.ContentId) {
            case '1':
                this.clean();
                this.router.navigate(['/tabs/tab1']);
                break;
            case '2':
                this.clean();
                this.router.navigate(['/BottleBarcode']);
                break;
        }
    }
}
